integrations.code:
// Signs the session cookie. Required in production; elsewhere a public dev-only
// default, so `kick dev` and the tests run without one.
SESSION_SECRET: z
  .string()
  .min(32)
  .default('dev-only-session-secret-not-for-production')
  // `: boolean` — inferring it would make this schema's type depend on
  // process.env, whose type `kick typegen` derives from this schema.
  .refine(
    (s): boolean => process.env.NODE_ENV !== 'production' || !s.startsWith('dev-only-'),
    { error: 'set it in production — the dev-only default is public' },
  )
